**助手**：
PWA确实可以在各种手机上发送系统级通知，包括状态栏图标、声音提醒和振动。这是PWA的标准功能之一，通过Web Push API实现。

```javascript
// 1. 请求通知权限
async function requestNotificationPermission() {
const permission = await Notification.requestPermission();
return permission === 'granted';
}
// 2. 注册Service Worker
async function registerServiceWorker() {
const registration = await navigator.serviceWorker.register('/service-worker.js');
return registration;
}
// 3. 订阅推送服务
async function subscribeToPushNotifications(registration) {
try {
const options = {
userVisibleOnly: true,
applicationServerKey: urlBase64ToUint8Array('YOUR_VAPID_PUBLIC_KEY')
};
const subscription = await registration.pushManager.subscribe(options);
// 将订阅信息发送到服务器
await fetch('/api/save-subscription', {
method: 'POST',
headers: { 'Content-Type': 'application/json' },
body: JSON.stringify(subscription)
});
return true;
} catch (error) {
console.error('Failed to subscribe to push notifications:', error);
return false;
}
}
// 4. 在Service Worker中处理推送消息
// service-worker.js
self.addEventListener('push', event => {
if (!event.data) return;
const data = event.data.json();
const options = {
body: data.message,
icon: '/images/notification-icon.png',
badge: '/images/badge-icon.png',
vibrate: [100, 50, 100], // 振动模式
sound: '/sounds/notification.mp3', // 声音
tag: data.tag || 'default', // 用于分组通知
actions: [
{ action: 'view', title: '查看任务' },
{ action: 'dismiss', title: '稍后处理' }
],
data: {
taskId: data.taskId,
url: data.url
}
};
event.waitUntil(
self.registration.showNotification(data.title, options)
);
});
// 5. 处理通知点击
self.addEventListener('notificationclick', event => {
event.notification.close();
if (event.action === 'dismiss') return;
const urlToOpen = event.notification.data.url || '/tasks';
event.waitUntil(
clients.openWindow(urlToOpen)
);
});
```

from pywebpush import webpush, WebPushException
def send_push_notification(subscription_info, title, message, task_id=None):
try:
webpush(
subscription_info=subscription_info,
data=json.dumps({
'title': title,
'message': message,
'taskId': task_id,
'url': f'/tasks/{task_id}' if task_id else '/tasks',
'tag': f'task-{task_id}' if task_id else 'notification'
}),
vapid_private_key='YOUR_VAPID_PRIVATE_KEY',
vapid_claims={
'sub': 'mailto:your@email.com'
}
)
return True
except WebPushException as e:
print(f"Push notification failed: {e}")
return False
```

