## 🔧 **核心API接口设计**

```javascript
class UnifiedStorageManager {

  // === 初始化 ===
  async initialize() {
    // 1. 加载JSON底座数据
    await this.loadJsonBase();

    // 2. 同步LocalStorage与JSON底座
    await this.syncLocalStorageWithJsonBase();

    // 3. 启动定期清理任务
    this.startCleanupTasks();

    // 4. 注册页面卸载事件
    this.registerUnloadHandlers();
  }

  // === 脑图数据管理 ===
  async saveMindmap(mindmapData) {
    // 1. 立即保存到LocalStorage
    const cacheKey = `mindmap_${mindmapData.id}`;
    const cacheData = {
      ...mindmapData,
      timestamp: Date.now(),
      dirty: true
    };
    localStorage.setItem(cacheKey, JSON.stringify(cacheData));

    // 2. 触发延迟同步到JSON底座
    this.scheduleJsonSync('mindmap', mindmapData.id);
  }

  async loadMindmap(mindmapId) {
    // 1. 优先从LocalStorage加载
    const cacheKey = `mindmap_${mindmapId}`;
    const cached = localStorage.getItem(cacheKey);

    if (cached) {
      const cacheData = JSON.parse(cached);
      if (!this.isCacheExpired(cacheData)) {
        return cacheData;
      }
    }

    // 2. 从JSON底座加载
    const jsonBase = await this.loadJsonBase();
    const mindmapData = jsonBase.mindmaps.find(m => m.id === mindmapId);

    if (mindmapData) {
      // 更新LocalStorage缓存
      localStorage.setItem(cacheKey, JSON.stringify({
        ...mindmapData,
        timestamp: Date.now(),
        dirty: false
      }));
    }

    return mindmapData;
  }

  // === 关系数据管理 ===
  async saveRelationData(mindmapId, relationData) {
    // 1. 立即保存到LocalStorage
    const cacheKey = `relation_${mindmapId}`;
    const cacheData = {
      mindmap_id: mindmapId,
      timestamp: Date.now(),
      ttl: this.getRelationCacheTTL(),
      data: relationData
    };
    localStorage.setItem(cacheKey, JSON.stringify(cacheData));

    // 2. 触发延迟同步到JSON底座
    this.scheduleJsonSync('relation', mindmapId);
  }

  async loadRelationData(mindmapId) {
    // 1. 检查LocalStorage缓存
    const cacheKey = `relation_${mindmapId}`;
    const cached = localStorage.getItem(cacheKey);

    if (cached) {
      const cacheData = JSON.parse(cached);
      if (Date.now() - cacheData.timestamp < cacheData.ttl) {
        return cacheData.data;
      }
    }

    // 2. 从JSON底座加载
    const jsonBase = await this.loadJsonBase();
    const relationData = jsonBase.relations?.[mindmapId];

    if (relationData) {
      // 更新LocalStorage缓存
      this.saveRelationData(mindmapId, relationData);
    }

    return relationData;
  }

  // === 应用状态管理 ===
  saveAppState(module, state) {
    const appStateKey = 'unified_app_state';
    const currentState = JSON.parse(localStorage.getItem(appStateKey) || '{}');

    currentState[module] = {
      ...state,
      timestamp: Date.now()
    };

    localStorage.setItem(appStateKey, JSON.stringify(currentState));

    // 延迟同步到JSON底座
    this.scheduleJsonSync('app_state', module);
  }

  loadAppState(module) {
    const appStateKey = 'unified_app_state';
    const appState = JSON.parse(localStorage.getItem(appStateKey) || '{}');
    return appState[module] || {};
  }

  // === 同步机制 ===
  scheduleJsonSync(dataType, identifier) {
    const syncKey = `${dataType}_${identifier}`;

    // 清除之前的同步任务
    if (this.syncTimers[syncKey]) {
      clearTimeout(this.syncTimers[syncKey]);
    }

    // 设置新的同步任务（5秒延迟）
    this.syncTimers[syncKey] = setTimeout(async () => {
      await this.syncToJsonBase(dataType, identifier);
      delete this.syncTimers[syncKey];
    }, 5000);
  }

  async syncToJsonBase(dataType, identifier) {
    try {
      const jsonBase = await this.loadJsonBase();

      switch (dataType) {
        case 'mindmap':
          await this.syncMindmapToJsonBase(jsonBase, identifier);
          break;
        case 'relation':
          await this.syncRelationToJsonBase(jsonBase, identifier);
          break;
        case 'app_state':
          await this.syncAppStateToJsonBase(jsonBase);
          break;
      }

      await this.saveJsonBase(jsonBase);

    } catch (error) {
      console.error(`[统一存储] ${dataType}同步失败:`, error);
    }
  }

  // === 缓存管理 ===
  cleanExpiredCache() {
    const now = Date.now();
    const keys = Object.keys(localStorage);

    keys.forEach(key => {
      if (key.startsWith('relation_')) {
        try {
          const cached = JSON.parse(localStorage.getItem(key));
          if (now - cached.timestamp > cached.ttl) {
            localStorage.removeItem(key);
            console.log(`[统一存储] 清理过期关系缓存: ${key}`);
          }
        } catch (error) {
          localStorage.removeItem(key);
          console.log(`[统一存储] 清理损坏缓存: ${key}`);
        }
      }
    });
  }

  // === 性能监控 ===
  updateCacheStatistics(operation, hit) {
    const stats = JSON.parse(localStorage.getItem('cache_stats') || '{}');
    stats[operation] = stats[operation] || {hits: 0, misses: 0};

    if (hit) {
      stats[operation].hits++;
    } else {
      stats[operation].misses++;
    }

    localStorage.setItem('cache_stats', JSON.stringify(stats));
  }
}
```

## 🎯 **关键特性与优势**

### 1. **分层缓存策略**
- **L1缓存**: LocalStorage (快速访问)
- **L2存储**: JSON底座 (持久化)
- **智能TTL**: 不同数据类型使用不同的过期时间

### 2. **防抖同步机制**
- 避免频繁的文件写入操作
- 批量处理多个修改
- 保证数据一致性

### 3. **自动清理机制**
- 定期清理过期缓存
- 监控存储使用量
- 智能垃圾回收

### 4. **错误恢复能力**
- 缓存损坏时自动重建
- 网络异常时的降级处理
- 数据版本冲突解决

这个设计确保了**高性能**、**高可靠性**和**良好的用户体验**，同时为关系图功能提供了坚实的数据基础。

