async function saveToJsonBase(updates) {
  const jsonBase = await loadJsonBase();

  // 1. 优先更新核心脑图数据
  if (updates.mindmaps) {
    jsonBase.mindmaps = updates.mindmaps;
    jsonBase.total_count = updates.mindmaps.length;
  }

  // 2. 更新扩展数据
  if (updates.relations) {
    jsonBase.relations = {...jsonBase.relations, ...updates.relations};
  }

  if (updates.notes) {
    jsonBase.notes = {...jsonBase.notes, ...updates.notes};
  }

