  const validation = JsonBaseValidator.validate(jsonBase);
  if (!validation.valid) {
    throw new Error(`数据验证失败: ${validation.errors.join(', ')}`);
  }

  // 5. 保存文件
  await writeJsonBase(jsonBase);
}
